import random


class TwentyFourPointGame:
    def __init__(self) -> None:
        self.nums = []

    def _generate_cards(self):
        for i in range(4):
            self.nums.append(random.randint(1, 9))
        assert len(self.nums) == 4

    def get_my_cards(self):
        self.nums = []
        self._generate_cards()
        return list(self.nums)

    def answer(self, expression):
        if expression == 'pass':
            return self.get_my_cards()
        if not self._expression_uses_valid_numbers(expression):
            return False
        return self.evaluate_expression(expression)

    def _expression_uses_valid_numbers(self, expression):
        statistic = {}
        for c in expression:
            if c.isdigit() and int(c) in self.nums:
                statistic[c] = statistic.get(c, 0) + 1

        nums_used = dict(statistic)

        for num in self.nums:
            num_str = str(num)
            if num_str in nums_used and nums_used[num_str] > 0:
                nums_used[num_str] -= 1
            else:
                return False

        return all(count == 0 for count in nums_used.values())

    def evaluate_expression(self, expression):
        try:
            return eval(expression) == 24
        except Exception:
            return False
